"""N3 saved-result report, gated on its separate audit receipt."""
import json
from pathlib import Path
H=Path(__file__).resolve().parent/'N3';O=H/'results'
def fmt(q):return f"{q['mean']:.6f} [{q['ci95'][0]:.6f}, {q['ci95'][1]:.6f}]"
def main():
    s=json.loads((O/'summary.json').read_text());audit=json.loads((O/'separate_verification.json').read_text());frozen=json.loads((O/'models/frozen_models.json').read_text());source=json.loads((O/'source_freeze.json').read_text());assert audit['games']['screen']['n_complete_blocks']==audit['games']['confirmation']['n_complete_blocks']==2000
    lines=['# N3 — late-play teacher distillation','','Status: self-checked(Codex), pending external audit. Local result packet only. Fixed-source two-card intervention, not an all-stage neural player.','','## Predeclared primary full-game comparisons','','All entries are points/game, n=2000complete matched nine-arm blocks per stage, paired seat-stratified95%normal CIs. Each hero rotates g%4; all seats use the canonical ModelBidder, with three TA opponents. These intervals condition on the frozen five-fit ensembles; they do not include refitting uncertainty.','','|Primary|Screen2130M|Fresh-deal confirmation2140M|','|---|---|---|']
    for name in ('PRIMARY_set-minus-hard','PRIMARY_best-minus-baseline'):lines.append(f"|{name}|{fmt(s['screen']['contrasts'][name]['score'])}|{fmt(s['confirmation']['contrasts'][name]['score'])}|")
    lines+=['','Validation-selected best student: `'+frozen['best_arm_name']+'`. Selected before held labels or either game stage. A non-significant result is not an equivalence result. Two co-primary contrasts and all exploratory controls are retained, without a familywise significance claim.','','## All game controls and table consequences','','|Contrast|Stage|Hero score|Ties-as-win change|Table total|Mean opponent score|','|---|---|---|---|---|---|']
    for stage in ('screen','confirmation'):
        for name,q in s[stage]['contrasts'].items():
            if name.startswith('exploratory_'):continue
            lines.append('|'+ '|'.join([name,stage,*[fmt(q[k]) for k in ('score','ties_as_win','table_score','opponents_mean_score')]])+'|')
    lines+=['','All four metrics above use n2000paired games/stage and95%seat-stratified normal CIs. Table/opponent effects are secondary general-sum consequences, not proof of optimal cooperation. Baseline absolute means and CIs, all totals, round scores and partial-arm recovery files are retained in raw JSON.','','|Exploratory selected-pipeline interaction|Screen|Confirmation|','|---|---|---|',f"|(MLPset−MLPhard)−(linearset−linearhard)|{fmt(s['screen']['contrasts']['exploratory_label_gain_interaction_MLP-minus-linear']['score'])}|{fmt(s['confirmation']['contrasts']['exploratory_label_gain_interaction_MLP-minus-linear']['score'])}|",'','This interaction is not an isolated nonlinearity effect: capacity, selected epochs and blends differ. The no-offset arm still receives baseline indicators; it tests explicit offset structure, not absence of baseline information.','','## Held finite-world teacher diagnostic','','n=2400independent conditional contexts,96fixed strata, K16shared worlds/context. CIs are paired/context-stratified95%normal intervals, not16independent samples per observation. This diagnostic uses a structural-uniform, PI-MaxN-continuation teacher surrogate; it is not actual TA continuation, a true posterior or a hidden-value certificate.','','|Decoder/student|Surrogate regret, mean[95%CI]|','|---|---|']
    for name,q in s['labels'].items():
        if name!='meta':lines.append(f'|{name}|{fmt(q)}|')
    lines+=['','Uniform-optimal and membership label-only ordering coincide with the two-action/public-hit-payoff finite-world optimum by the restricted M15 identity. Any zero diagnostic is that surrogate identity, not an empirical claim of zero true-game regret. Hard labels choose the lowest card in each tied world. The reported teacher-label gap is separate from finite neural optimization and full-game outcomes.','','## Selection and reproducibility','','|Arm|Epochs, five fits|Blends, five fits|','|---|---|---|']
    for arm in frozen['arms']:lines.append(f"|{arm['name']}|{', '.join(str(r['epoch']) for r in arm['models'])}|{', '.join(str(r['alpha']) for r in arm['models'])}|")
    lines+=['','Epochs5/10/25/50and blends0/.25/.5/1were selected on reused2400validation contexts, then ensembles ranked on that same finite-K surrogate. Candidate CIs are descriptive selection diagnostics. Search endpoints do not certify optima. Train9600contexts, SHA-original-own-hand split, held-label2400contexts; pilot192excluded. Equal accepted96strata upweight rare active round types, while utility tests are unfiltered fresh games including all hand partitions. No held-context tuning or sample extension.','','Pre-run source commit: `'+source['pre_run_source_commit']+'`; source fingerprint `'+source['source_fingerprint']+'`. Five paired initialization/batch schedules use2120M/domain0x4E33, with actual attempt roots and child-state collision checks in the journal. Runtime bounds, original raw worlds/prefixes, Adam checkpoints, selected models, stage totals and every uncertainty calculation are retained.','','Separate checks: every saved context/teacher world uses fresh manual deal/rules/solver replay (sampler and fixed policies reused as definitions), all40model choices and held-context CIs checked, every game score/hook/tie/paired CI recomputed, and144full games independently replayed with a manual engine and numerical forward pass. This is same-investigator cross-checking, not external validation.','','The conditional dataset, summarized observations, finiteK, teacher/opponent mismatch and narrow opponent pool limit scope. Neither game improvement nor a null identifies pure loss-function dynamics, a general hidden-information optimum, human benefit or novelty. No publication release is implied.']
    (H/'RESULTS.md').write_text('\n'.join(lines)+'\n',encoding='utf-8');print('N3 RESULTS generated from completed/audited packet')
if __name__=='__main__':main()
